-- SickleStrong — database security model (GENERATED SNAPSHOT, DO NOT APPLY)
--
-- Generated by db/dump-security-model.sql on 2026-10-20 19:00 UTC.
-- This is a REVIEW ARTIFACT, not a migration. The live database is the
-- source of truth; this file exists so the access rules can be read,
-- diffed, and code-reviewed alongside the frontend that depends on them.
-- Do not run it against a database.
--
-- The promise these rules enforce: every table holding a child's health
-- data is scoped by child_access (via accessible_child_ids /
-- full_access_child_ids / report_access_child_ids), never by family_id.
-- Being in a household is not access to a child.



-- ============================================================
-- ACCESS HELPERS — every policy below resolves through these
-- ============================================================

CREATE OR REPLACE FUNCTION public.accessible_child_ids()
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT child_id FROM public.child_access WHERE auth_id = auth.uid();
$function$

CREATE OR REPLACE FUNCTION public.full_access_child_ids()
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT child_id FROM public.child_access WHERE auth_id = auth.uid() AND permission = 'full';
$function$

CREATE OR REPLACE FUNCTION public.is_parent_of_child(p_child_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.child_access
    WHERE child_id = p_child_id AND auth_id = auth.uid() AND circle_role = 'parent'
  );
$function$

CREATE OR REPLACE FUNCTION public.report_access_child_ids()
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT child_id FROM public.child_access WHERE auth_id = auth.uid() AND permission IN ('report','full');
$function$



-- ============================================================
-- SECURITY DEFINER RPCs — the only way access is ever granted
-- ============================================================

CREATE OR REPLACE FUNCTION public.approve_teen_request(p_code text, p_child_id uuid, p_permission text DEFAULT 'report'::text)
 RETURNS TABLE(out_child_name text, out_teen_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  r     public.teen_signup_requests%ROWTYPE;
  v_me  text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'NOT_AUTHENTICATED'; END IF;
  IF p_permission NOT IN ('full','report','view') THEN RAISE EXCEPTION 'INVALID_PERMISSION'; END IF;
  SELECT * INTO r FROM public.teen_signup_requests WHERE code = upper(trim(p_code)) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'REQUEST_NOT_FOUND'; END IF;
  IF r.status <> 'pending' THEN RAISE EXCEPTION 'REQUEST_ALREADY_USED'; END IF;
  IF r.expires_at <= now() THEN RAISE EXCEPTION 'REQUEST_EXPIRED'; END IF;
  SELECT lower(email) INTO v_me FROM auth.users WHERE id = v_uid;
  IF v_me IS DISTINCT FROM r.parent_email THEN RAISE EXCEPTION 'NOT_THE_NAMED_PARENT'; END IF;
  IF v_uid = r.teen_auth_id THEN RAISE EXCEPTION 'NOT_THE_NAMED_PARENT'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.child_access
                 WHERE child_id = p_child_id AND auth_id = v_uid AND circle_role = 'parent') THEN
    RAISE EXCEPTION 'NOT_A_PARENT_FOR_THIS_CHILD';
  END IF;

  INSERT INTO public.child_access (child_id, auth_id, permission, circle_role, invited_by)
  VALUES (p_child_id, r.teen_auth_id, p_permission, 'caregiver', v_uid)
  ON CONFLICT (child_id, auth_id) DO UPDATE SET permission = EXCLUDED.permission;

  UPDATE public.teen_signup_requests
     SET status = 'approved', child_id = p_child_id, approved_by = v_uid
   WHERE id = r.id;

  out_child_name := (SELECT name FROM public.children WHERE id = p_child_id);
  out_teen_name := r.teen_name;
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.block_teen_child_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NOT NULL AND public.is_teen_account(auth.uid()) THEN
    RAISE EXCEPTION 'TEEN_NEEDS_PARENT';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_child_invite(p_invite_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_child_id uuid;
BEGIN
  SELECT child_id INTO v_child_id FROM public.child_invites WHERE id = p_invite_id;
  IF v_child_id IS NULL THEN
    RAISE EXCEPTION 'INVITE_NOT_FOUND';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.child_access ca
    WHERE ca.child_id = v_child_id AND ca.auth_id = auth.uid() AND ca.circle_role = 'parent'
  ) THEN
    RAISE EXCEPTION 'NOT_A_PARENT_FOR_THIS_CHILD';
  END IF;

  UPDATE public.child_invites SET revoked_at = now()
  WHERE id = p_invite_id AND revoked_at IS NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_teen_request(p_parent_email text)
 RETURNS TABLE(out_code text, out_parent_email text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid   uuid := auth.uid();
  v_email text := lower(trim(coalesce(p_parent_email, '')));
  v_own   text;
  v_name  text;
  v_code  text;
  i       int;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'NOT_AUTHENTICATED'; END IF;
  IF NOT public.is_teen_account(v_uid) THEN RAISE EXCEPTION 'NOT_A_TEEN_ACCOUNT'; END IF;
  IF v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN RAISE EXCEPTION 'PARENT_EMAIL_INVALID'; END IF;
  SELECT lower(email), raw_user_meta_data->>'full_name' INTO v_own, v_name FROM auth.users WHERE id = v_uid;
  IF v_email = v_own THEN RAISE EXCEPTION 'PARENT_EMAIL_IS_OWN'; END IF;

  UPDATE public.teen_signup_requests SET status = 'cancelled'
   WHERE teen_auth_id = v_uid AND status = 'pending' AND expires_at <= now();

  UPDATE public.teen_signup_requests SET parent_email = v_email
   WHERE teen_auth_id = v_uid AND status = 'pending'
   RETURNING code INTO v_code;
  IF v_code IS NOT NULL THEN
    out_code := v_code; out_parent_email := v_email; RETURN NEXT; RETURN;
  END IF;

  FOR i IN 1..10 LOOP
    v_code := 'TEEN-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 8));
    BEGIN
      INSERT INTO public.teen_signup_requests (teen_auth_id, teen_name, parent_email, code)
      VALUES (v_uid, v_name, v_email, v_code);
      out_code := v_code; out_parent_email := v_email; RETURN NEXT; RETURN;
    EXCEPTION WHEN unique_violation THEN
      IF i = 10 THEN RAISE EXCEPTION 'Could not allocate a request code'; END IF;
    END;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_child_permanently(p_child_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.child_access ca
    WHERE ca.child_id = p_child_id AND ca.auth_id = auth.uid() AND ca.circle_role = 'parent'
  ) THEN
    RAISE EXCEPTION 'NOT_A_PARENT_FOR_THIS_CHILD';
  END IF;

  ALTER TABLE public.child_access DISABLE TRIGGER child_access_prevent_last_parent;
  DELETE FROM public.contacts WHERE child_id = p_child_id;
  DELETE FROM public.medication_logs WHERE child_id = p_child_id;
  DELETE FROM public.children WHERE id = p_child_id;
  ALTER TABLE public.child_access ENABLE TRIGGER child_access_prevent_last_parent;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_my_account()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid       uuid := auth.uid();
  v_user      public.users%ROWTYPE;
  v_has_user  boolean;
  v_blockers  text;
  v_child     record;
  v_new_fam   uuid;
  v_tbl       text;
  -- Child-scoped tables that carry a family_id (NO ACTION / CASCADE FKs to families).
  v_tables    text[] := ARRAY['contacts','doctor_reports','hydration_logs','medication_logs',
                              'medications','notes','pain_logs','symptoms','temperature_logs','weight_logs'];
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;

  -- A child must never be left without a parent. If the caller is the only
  -- parent on any child, refuse and name those children so the app can say
  -- what to do: add another parent, or delete the child first.
  SELECT string_agg(c.name, ', ' ORDER BY c.name) INTO v_blockers
  FROM public.child_access ca
  JOIN public.children c ON c.id = ca.child_id
  WHERE ca.auth_id = v_uid AND ca.circle_role = 'parent'
    AND NOT EXISTS (
      SELECT 1 FROM public.child_access o
      WHERE o.child_id = ca.child_id AND o.circle_role = 'parent' AND o.auth_id <> v_uid
    );
  IF v_blockers IS NOT NULL THEN
    RAISE EXCEPTION 'SOLE_PARENT_OF_CHILDREN' USING DETAIL = v_blockers;
  END IF;

  SELECT * INTO v_user FROM public.users WHERE auth_id = v_uid;
  v_has_user := FOUND;

  IF v_has_user THEN
    -- Entries this person logged on children who stay (shared with another
    -- parent) remain part of that child's history; only the author is removed.
    UPDATE public.pain_logs        SET logged_by    = NULL WHERE logged_by    = v_user.id;
    UPDATE public.temperature_logs SET logged_by    = NULL WHERE logged_by    = v_user.id;
    UPDATE public.symptoms         SET logged_by    = NULL WHERE logged_by    = v_user.id;
    UPDATE public.weight_logs      SET logged_by    = NULL WHERE logged_by    = v_user.id;
    UPDATE public.hydration_logs   SET logged_by    = NULL WHERE logged_by    = v_user.id;
    UPDATE public.medication_logs  SET logged_by    = NULL WHERE logged_by    = v_user.id;
    UPDATE public.notes            SET created_by   = NULL WHERE created_by   = v_user.id;
    UPDATE public.doctor_reports   SET generated_by = NULL WHERE generated_by = v_user.id;
    DELETE FROM public.community_posts WHERE author_id = v_user.id;
  END IF;

  UPDATE public.child_access SET invited_by = NULL WHERE invited_by = v_uid;
  DELETE FROM public.child_invites WHERE created_by = v_uid;
  -- Safe under the last-parent trigger: the check above guarantees every
  -- parent row removed here leaves another parent behind.
  DELETE FROM public.child_access WHERE auth_id = v_uid;

  IF v_has_user THEN
    DELETE FROM public.users WHERE id = v_user.id;

    IF v_user.family_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM public.users WHERE family_id = v_user.family_id) THEN
      -- The household is now empty. Children in it that someone else can still
      -- reach move to that person's household, with their records; the rest
      -- are unreachable and are removed.
      FOR v_child IN SELECT id FROM public.children WHERE family_id = v_user.family_id LOOP
        v_new_fam := NULL;
        SELECT u.family_id INTO v_new_fam
        FROM public.child_access ca JOIN public.users u ON u.auth_id = ca.auth_id
        WHERE ca.child_id = v_child.id AND u.family_id IS NOT NULL
        ORDER BY (ca.circle_role = 'parent') DESC, ca.created_at
        LIMIT 1;

        IF v_new_fam IS NOT NULL THEN
          UPDATE public.children SET family_id = v_new_fam WHERE id = v_child.id;
        ELSE
          ALTER TABLE public.child_access DISABLE TRIGGER child_access_prevent_last_parent;
          DELETE FROM public.contacts        WHERE child_id = v_child.id;
          DELETE FROM public.medication_logs WHERE child_id = v_child.id;
          DELETE FROM public.children        WHERE id = v_child.id;
          ALTER TABLE public.child_access ENABLE TRIGGER child_access_prevent_last_parent;
        END IF;
      END LOOP;

      -- Records stamped with this household but belonging to a child that
      -- lives elsewhere follow their child, so deleting the household can't
      -- take another family's records with it.
      FOREACH v_tbl IN ARRAY v_tables LOOP
        EXECUTE format(
          'UPDATE public.%I t SET family_id = c.family_id FROM public.children c
            WHERE t.child_id = c.id AND t.family_id = $1 AND c.family_id IS DISTINCT FROM $1',
          v_tbl) USING v_user.family_id;
      END LOOP;

      DELETE FROM public.community_posts WHERE family_id = v_user.family_id;
      DELETE FROM public.families WHERE id = v_user.family_id;
    END IF;
  END IF;

  DELETE FROM auth.users WHERE id = v_uid;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_child_invite(p_child_id uuid, p_permission text, p_circle_role text DEFAULT 'caregiver'::text)
 RETURNS TABLE(out_code text, out_expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid  uuid := auth.uid();
  v_code text;
  i      int;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;

  IF p_permission NOT IN ('full','report','view') THEN
    RAISE EXCEPTION 'INVALID_PERMISSION';
  END IF;
  IF p_circle_role NOT IN ('parent','caregiver') THEN
    RAISE EXCEPTION 'INVALID_CIRCLE_ROLE';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.child_access ca
    WHERE ca.child_id = p_child_id AND ca.auth_id = v_uid AND ca.circle_role = 'parent'
  ) THEN
    RAISE EXCEPTION 'NOT_A_PARENT_FOR_THIS_CHILD';
  END IF;

  FOR i IN 1..10 LOOP
    v_code := 'INV-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 8));
    BEGIN
      INSERT INTO public.child_invites (child_id, code, permission, circle_role, created_by)
      VALUES (p_child_id, v_code, p_permission, p_circle_role, v_uid)
      RETURNING code, expires_at INTO out_code, out_expires_at;
      RETURN NEXT;
      RETURN;
    EXCEPTION WHEN unique_violation THEN
      IF i = 10 THEN RAISE EXCEPTION 'Could not allocate an invite code'; END IF;
    END;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_push_config()
 RETURNS json
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT json_build_object('vapid_public_key', vapid_public_key, 'vapid_private_key', vapid_private_key,
                           'vapid_subject', vapid_subject, 'cron_secret', cron_secret)
  FROM private.push_config WHERE id;
$function$

CREATE OR REPLACE FUNCTION public.grant_owner_child_access()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NOT NULL THEN
    INSERT INTO public.child_access (child_id, auth_id, permission, circle_role, invited_by)
    VALUES (NEW.id, auth.uid(), 'full', 'parent', auth.uid())
    ON CONFLICT (child_id, auth_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.is_teen_account(p_uid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT coalesce((SELECT raw_user_meta_data->>'age_band' FROM auth.users WHERE id = p_uid), '') = '13-17';
$function$

CREATE OR REPLACE FUNCTION public.lookup_family_by_code(p_code text)
 RETURNS TABLE(out_family_id uuid, out_family_code text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT id, family_code FROM public.families
  WHERE family_code = upper(trim(p_code)) AND is_active = true
  LIMIT 1;
$function$

CREATE OR REPLACE FUNCTION public.lookup_teen_request(p_code text)
 RETURNS TABLE(out_teen_name text, out_status text, out_expired boolean, out_email_matches boolean, out_parent_email_hint text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  r     public.teen_signup_requests%ROWTYPE;
  v_me  text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'NOT_AUTHENTICATED'; END IF;
  SELECT * INTO r FROM public.teen_signup_requests WHERE code = upper(trim(p_code));
  IF NOT FOUND THEN RAISE EXCEPTION 'REQUEST_NOT_FOUND'; END IF;
  SELECT lower(email) INTO v_me FROM auth.users WHERE id = v_uid;
  out_teen_name := r.teen_name;
  out_status := r.status;
  out_expired := r.expires_at <= now();
  out_email_matches := (v_me = r.parent_email);
  out_parent_email_hint := left(r.parent_email, 1) || '•••@' || split_part(r.parent_email, '@', 2);
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.note_push_failure(p_id uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  UPDATE public.push_subscriptions SET failures = failures + 1 WHERE id = p_id;
  DELETE FROM public.push_subscriptions WHERE id = p_id AND failures >= 10;
$function$

CREATE OR REPLACE FUNCTION public.prevent_last_parent_removal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.circle_role = 'parent' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.child_access
      WHERE child_id = OLD.child_id AND circle_role = 'parent' AND auth_id <> OLD.auth_id
    ) THEN
      RAISE EXCEPTION 'LAST_PARENT_CANNOT_BE_REMOVED';
    END IF;
  END IF;
  RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.provision_current_user(p_full_name text DEFAULT NULL::text, p_role text DEFAULT 'parent'::text, p_join_code text DEFAULT NULL::text, p_child_code text DEFAULT NULL::text)
 RETURNS TABLE(out_family_id uuid, out_family_code text, out_full_name text, out_created boolean, out_joined_child_id uuid, out_joined_child_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid     uuid := auth.uid();
  v_email   text;
  v_name    text;
  v_exist   public.users%ROWTYPE;
  v_fam     public.families%ROWTYPE;
  v_code    text;
  v_created boolean := false;
  v_words   text[] := ARRAY['STRONG','BRAVE','CARE','HOPE','LOVE','HEAL','BOND','SAFE'];
  i         int;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;

  IF p_child_code IS NOT NULL AND length(trim(p_child_code)) > 0 THEN
    RAISE EXCEPTION 'LEGACY_CHILD_CODE_DISABLED';
  END IF;

  -- Retired for the same reason as p_child_code. Household codes are low
  -- entropy (8 words x 9000), so a guessed one used to place a brand new
  -- account inside a real family's household. switch_household already
  -- refuses a guessed code unless the caller holds access to a child there,
  -- but a fresh signup never does, so the same gate cannot be applied here --
  -- the path itself has to go. redeem_child_invite covers the legitimate
  -- case: it creates the profile AND puts them in the child's household.
  IF p_join_code IS NOT NULL AND length(trim(p_join_code)) > 0 THEN
    RAISE EXCEPTION 'HOUSEHOLD_CODE_SIGNUP_DISABLED';
  END IF;

  SELECT email, coalesce(p_full_name, raw_user_meta_data->>'full_name', email)
    INTO v_email, v_name
  FROM auth.users WHERE id = v_uid;

  SELECT * INTO v_exist FROM public.users WHERE auth_id = v_uid;
  IF FOUND THEN
    SELECT * INTO v_fam FROM public.families WHERE id = v_exist.family_id;
    v_name := coalesce(v_exist.full_name, v_name);
  ELSE
    -- Always a household of their own now. An invite link is what moves
    -- someone into an existing family.
    FOR i IN 1..10 LOOP
      v_code := v_words[1 + floor(random() * array_length(v_words,1))::int]
                || '-' || lpad((1000 + floor(random()*9000))::int::text, 4, '0');
      BEGIN
        INSERT INTO public.families (family_code, plan) VALUES (v_code, 'beta')
          RETURNING * INTO v_fam;
        EXIT;
      EXCEPTION WHEN unique_violation THEN
        IF i = 10 THEN RAISE EXCEPTION 'Could not allocate a family code'; END IF;
      END;
    END LOOP;

    INSERT INTO public.users (auth_id, family_id, full_name, email, role, is_primary)
    VALUES (v_uid, v_fam.id, v_name, v_email, coalesce(p_role, 'parent'), true)
    ON CONFLICT (auth_id) DO NOTHING;

    v_created := true;
  END IF;

  RETURN QUERY SELECT v_fam.id, v_fam.family_code, v_name, v_created, NULL::uuid, NULL::text;
END;
$function$

CREATE OR REPLACE FUNCTION public.redeem_child_invite(p_code text, p_full_name text DEFAULT NULL::text)
 RETURNS TABLE(out_family_id uuid, out_family_code text, out_full_name text, out_child_id uuid, out_child_name text, out_permission text, out_circle_role text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid    uuid := auth.uid();
  v_email  text;
  v_name   text;
  v_exist  public.users%ROWTYPE;
  v_fam    public.families%ROWTYPE;
  v_child  public.children%ROWTYPE;
  v_invite public.child_invites%ROWTYPE;
  v_count  int;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;

  SELECT * INTO v_invite FROM public.child_invites
    WHERE code = upper(trim(p_code));
  IF NOT FOUND THEN
    RAISE EXCEPTION 'INVALID_INVITE_CODE';
  END IF;
  IF v_invite.revoked_at IS NOT NULL THEN
    RAISE EXCEPTION 'INVITE_REVOKED';
  END IF;
  IF v_invite.used_at IS NOT NULL THEN
    RAISE EXCEPTION 'INVITE_ALREADY_USED';
  END IF;
  IF v_invite.expires_at < now() THEN
    RAISE EXCEPTION 'INVITE_EXPIRED';
  END IF;

  SELECT * INTO v_child FROM public.children WHERE id = v_invite.child_id AND is_active = true;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'CHILD_NOT_FOUND';
  END IF;

  SELECT email, coalesce(p_full_name, raw_user_meta_data->>'full_name', email)
    INTO v_email, v_name
  FROM auth.users WHERE id = v_uid;

  SELECT * INTO v_exist FROM public.users WHERE auth_id = v_uid;
  IF FOUND THEN
    SELECT * INTO v_fam FROM public.families WHERE id = v_exist.family_id;
    v_name := coalesce(v_exist.full_name, v_name);
  ELSE
    SELECT * INTO v_fam FROM public.families WHERE id = v_child.family_id;
    INSERT INTO public.users (auth_id, family_id, full_name, email, role, is_primary)
    VALUES (v_uid, v_fam.id, v_name, v_email,
            CASE WHEN v_invite.circle_role = 'parent' THEN 'parent' ELSE 'caregiver' END,
            false)
    ON CONFLICT (auth_id) DO NOTHING;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.child_access ca WHERE ca.child_id = v_child.id AND ca.auth_id = v_uid
  ) THEN
    SELECT count(*) INTO v_count FROM public.child_access ca WHERE ca.child_id = v_child.id;
    IF v_count >= 5 THEN
      RAISE EXCEPTION 'CHILD_CAREGIVER_LIMIT';
    END IF;
    INSERT INTO public.child_access (child_id, auth_id, permission, circle_role, invited_by)
    VALUES (v_child.id, v_uid, v_invite.permission, v_invite.circle_role, v_invite.created_by);
  END IF;

  UPDATE public.child_invites SET used_at = now(), used_by = v_uid WHERE id = v_invite.id;

  RETURN QUERY SELECT v_fam.id, v_fam.family_code, v_name, v_child.id, v_child.name,
                      v_invite.permission, v_invite.circle_role;
END;
$function$

CREATE OR REPLACE FUNCTION public.remove_push_subscription(p_endpoint text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  DELETE FROM public.push_subscriptions WHERE endpoint = p_endpoint AND auth_id = auth.uid();
$function$

CREATE OR REPLACE FUNCTION public.save_push_subscription(p_endpoint text, p_p256dh text, p_auth text, p_time_zone text, p_show_names boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid  uuid := auth.uid();
  v_host text := lower(substring(coalesce(p_endpoint, '') from '^https://([^/:?#]+)'));
  v_tz   text := coalesce(nullif(trim(p_time_zone), ''), 'America/Chicago');
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'NOT_AUTHENTICATED'; END IF;
  -- The edge function POSTs to this URL, so only real push services are
  -- accepted — otherwise anyone could point it at an address of their choosing.
  IF v_host IS NULL OR length(p_endpoint) > 1024 OR NOT (
       v_host = 'fcm.googleapis.com' OR v_host = 'updates.push.services.mozilla.com'
    OR v_host = 'web.push.apple.com' OR v_host LIKE '%.push.apple.com'
    OR v_host LIKE '%.notify.windows.com') THEN
    RAISE EXCEPTION 'PUSH_ENDPOINT_NOT_ALLOWED';
  END IF;
  IF p_p256dh !~ '^[A-Za-z0-9_-]{86,88}$' OR p_auth !~ '^[A-Za-z0-9_-]{21,24}$' THEN
    RAISE EXCEPTION 'PUSH_KEYS_INVALID';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = v_tz) THEN v_tz := 'America/Chicago'; END IF;

  DELETE FROM public.push_subscriptions WHERE endpoint = p_endpoint AND auth_id <> v_uid;
  INSERT INTO public.push_subscriptions (auth_id, endpoint, p256dh, auth, time_zone, show_names)
  VALUES (v_uid, p_endpoint, p_p256dh, p_auth, v_tz, coalesce(p_show_names, false))
  ON CONFLICT (endpoint) DO UPDATE
    SET p256dh = EXCLUDED.p256dh, auth = EXCLUDED.auth, time_zone = EXCLUDED.time_zone,
        show_names = EXCLUDED.show_names, failures = 0;
END $function$

CREATE OR REPLACE FUNCTION public.set_child_active_status(p_child_id uuid, p_active boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.child_access ca
    WHERE ca.child_id = p_child_id AND ca.auth_id = auth.uid() AND ca.circle_role = 'parent'
  ) THEN
    RAISE EXCEPTION 'NOT_A_PARENT_FOR_THIS_CHILD';
  END IF;
  UPDATE public.children SET is_active = p_active WHERE id = p_child_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.stamp_created_by()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NOT NULL THEN
    NEW.created_by := (SELECT id FROM public.users WHERE auth_id = auth.uid());
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.stamp_logged_by()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NOT NULL THEN
    NEW.logged_by := (SELECT id FROM public.users WHERE auth_id = auth.uid());
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.switch_household(p_join_code text)
 RETURNS TABLE(out_family_id uuid, out_family_code text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_fam public.families%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;

  IF p_join_code IS NULL OR length(trim(p_join_code)) = 0 THEN
    RAISE EXCEPTION 'INVALID_FAMILY_CODE';
  END IF;

  SELECT * INTO v_fam FROM public.families
    WHERE family_code = upper(trim(p_join_code)) AND is_active = true;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'INVALID_FAMILY_CODE';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.users WHERE auth_id = v_uid) THEN
    RAISE EXCEPTION 'NOT_PROVISIONED';
  END IF;

  IF EXISTS (SELECT 1 FROM public.users WHERE auth_id = v_uid AND family_id = v_fam.id) THEN
    RETURN QUERY SELECT v_fam.id, v_fam.family_code;
    RETURN;
  END IF;

  -- The new gate: you must already have been invited to a child in that
  -- household. A correct-but-guessed code is not enough on its own.
  IF NOT EXISTS (
    SELECT 1
    FROM public.child_access ca
    JOIN public.children c ON c.id = ca.child_id
    WHERE ca.auth_id = v_uid AND c.family_id = v_fam.id
  ) THEN
    RAISE EXCEPTION 'NOT_INVITED_TO_THIS_HOUSEHOLD';
  END IF;

  UPDATE public.users SET family_id = v_fam.id, is_primary = false WHERE auth_id = v_uid;

  RETURN QUERY SELECT v_fam.id, v_fam.family_code;
END;
$function$



