ALTER TABLE public.child_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY child_access_delete ON public.child_access
  FOR DELETE TO public
  USING (((auth_id = auth.uid()) OR is_parent_of_child(child_id)));
CREATE POLICY child_access_select ON public.child_access
  FOR SELECT TO public
  USING ((child_id IN ( SELECT accessible_child_ids() AS accessible_child_ids)));
ALTER TABLE public.child_invites ENABLE ROW LEVEL SECURITY;
