   FROM child_access ca
  WHERE ((ca.child_id = child_invites.child_id) AND (ca.auth_id = auth.uid()) AND (ca.circle_role = 'parent'::text)))));
CREATE POLICY child_invites_update ON public.child_invites
  FOR UPDATE TO public
  USING ((EXISTS ( SELECT 1
   FROM child_access ca
